package engine

import (
	"fmt"
	"math"
	"math/big"
	"strings"
)

// An exact generator of the {p,q} tiling, independent of the shipped one
// (#389). The tiling's symmetry group is the triangle group generated by
// reflections s1, s2, s3 in the sides of a triangle with angles π/p (at a
// tile's center, between mirrors 1 and 2), π/q (at a corner, between
// mirrors 2 and 3) and π/2 (at a side's midpoint, between mirrors 1 and 3).
// In Tits' geometric representation, s_i(α_j) = α_j + c_ij·α_i with
// c_ij = 2cos(π/m_ij), and s_i(α_i) = −α_i. Every entry lies in the ring
// ℤ[2cos π/p, 2cos π/q], so the action is computed in integers.
//
// Points are dual vectors f, with f_j = f(α_j): a tile's center is the
// image of ω3, fixed by s1 and s2; a corner of ω1, fixed by s2 and s3; a
// side's midpoint of ω2, fixed by s1 and s3. Two transformations reach the
// same tile exactly when they carry ω3 to the same vector, so a tile, a
// vertex and an edge are identified by exact integer vectors, with no
// tolerance. Generation follows the same breadth-first order and the same
// labeling of sides as the shipped generator, so its tiles, addresses and
// incidence can be compared one for one.

// xring is an element of ℤ[a, b], a = 2cos(π/p) and b = 2cos(π/q), on the
// basis a^i·b^j, i < deg a, j < deg b, as coefficient index i·deg b + j.
type xring []int64

// xfield describes ℤ[a, b] by the minimal polynomials of a and b.
type xfield struct {
	p, q   int
	da, db int
	// Powers a^k and b^k for k < 2·deg, as coefficients on 1, a, a², ….
	powA, powB [][]int64
	// Numeric values of a and b at 200 bits, for conversion.
	a, b *big.Float
}

// minimal is the monic minimal polynomial of 2cos(π/m), lowest degree
// first without the leading 1: x − 1 for m = 3, x² − 2 for 4, x² − x − 1
// for 5, x² − 3 for 6, x³ − x² − 2x + 1 for 7, x⁴ − 4x² + 2 for 8.
func minimal(m int) []int64 {
	switch m {
	case 3:
		return []int64{-1}
	case 4:
		return []int64{-2, 0}
	case 5:
		return []int64{-1, -1}
	case 6:
		return []int64{-3, 0}
	case 7:
		return []int64{1, -2, -1}
	case 8:
		return []int64{2, 0, -4, 0}
	}
	panic(fmt.Sprintf("no minimal polynomial for 2cos(π/%d)", m))
}

// powers reduces x^k, k < 2d − 1, modulo the minimal polynomial.
func powers(m []int64) [][]int64 {
	d := len(m)
	out := [][]int64{}
	cur := make([]int64, d)
	cur[0] = 1
	for k := 0; k < 2*d; k++ {
		out = append(out, append([]int64(nil), cur...))
		// x·cur, with x^d = −Σ m_i x^i.
		top := cur[d-1]
		next := make([]int64, d)
		for i := d - 1; i > 0; i-- {
			next[i] = cur[i-1]
		}
		for i := range d {
			next[i] -= top * m[i]
		}
		cur = next
	}
	return out
}

// twoCos is 2cos(π/m) to 200 bits: Newton's method on its minimal
// polynomial x^d + Σ m_i x^i from the float64 value.
func twoCos(m int) *big.Float {
	poly := append(minimal(m), 1)
	x := new(big.Float).SetPrec(200).SetFloat64(2 * math.Cos(math.Pi/float64(m)))
	for range 8 {
		f := new(big.Float).SetPrec(200)
		df := new(big.Float).SetPrec(200)
		for i := len(poly) - 1; i >= 0; i-- {
			// Horner: df = df·x + f, then f = f·x + c_i.
			df.Mul(df, x).Add(df, f)
			f.Mul(f, x).Add(f, new(big.Float).SetInt64(poly[i]))
		}
		x.Sub(x, new(big.Float).SetPrec(200).Quo(f, df))
	}
	return x
}

func newXField(p, q int) *xfield {
	ma, mb := minimal(p), minimal(q)
	return &xfield{p: p, q: q, da: len(ma), db: len(mb), powA: powers(ma), powB: powers(mb), a: twoCos(p), b: twoCos(q)}
}

func (f *xfield) zero() xring { return make(xring, f.da*f.db) }
func (f *xfield) one() xring  { r := f.zero(); r[0] = 1; return r }

// gen is a (which 0) or b (which 1) as a ring element; a degree-one
// generator is the integer it equals.
func (f *xfield) gen(which int) xring {
	r := f.zero()
	if which == 0 {
		if f.da == 1 {
			r[0] = -minimal(f.p)[0]
		} else {
			r[1*f.db] = 1
		}
	} else {
		if f.db == 1 {
			r[0] = -minimal(f.q)[0]
		} else {
			r[1] = 1
		}
	}
	return r
}

// exactBound is where an exact coefficient would leave the range in which
// sums and products stay below 2⁶³; the oracle refuses beyond it.
const exactBound = 1 << 28

func (f *xfield) add(x, y xring) xring {
	r := f.zero()
	for i := range r {
		r[i] = x[i] + y[i]
	}
	return r
}

func (f *xfield) neg(x xring) xring {
	r := f.zero()
	for i := range r {
		r[i] = -x[i]
	}
	return r
}

func (f *xfield) mul(x, y xring) xring {
	r := f.zero()
	for i1 := range f.da {
		for j1 := range f.db {
			u := x[i1*f.db+j1]
			if u == 0 {
				continue
			}
			for i2 := range f.da {
				for j2 := range f.db {
					v := y[i2*f.db+j2]
					if v == 0 {
						continue
					}
					pa, pb := f.powA[i1+i2], f.powB[j1+j2]
					for i := range f.da {
						if pa[i] == 0 {
							continue
						}
						for j := range f.db {
							r[i*f.db+j] += u * v * pa[i] * pb[j]
						}
					}
				}
			}
		}
	}
	for _, c := range r {
		if c > exactBound || c < -exactBound {
			panic("exact coefficient beyond the oracle's bound")
		}
	}
	return r
}

// value is x as a 200-bit float.
func (f *xfield) value(x xring) *big.Float {
	s := new(big.Float).SetPrec(200)
	for i := range f.da {
		for j := range f.db {
			c := x[i*f.db+j]
			if c == 0 {
				continue
			}
			t := new(big.Float).SetPrec(200).SetInt64(c)
			for range i {
				t.Mul(t, f.a)
			}
			for range j {
				t.Mul(t, f.b)
			}
			s.Add(s, t)
		}
	}
	return s
}

func (x xring) key() string {
	var b strings.Builder
	for _, c := range x {
		fmt.Fprintf(&b, "%d,", c)
	}
	return b.String()
}

// xmat is a 3×3 matrix over the ring, rows by columns.
type xmat [3][3]xring

func (f *xfield) identity() xmat {
	var m xmat
	for i := range 3 {
		for j := range 3 {
			if i == j {
				m[i][j] = f.one()
			} else {
				m[i][j] = f.zero()
			}
		}
	}
	return m
}

func (f *xfield) mulMat(x, y xmat) xmat {
	var m xmat
	for i := range 3 {
		for j := range 3 {
			s := f.zero()
			for k := range 3 {
				s = f.add(s, f.mul(x[i][k], y[k][j]))
			}
			m[i][j] = s
		}
	}
	return m
}

// simple is s_i's matrix on the root basis: the identity except row i,
// whose entries are c_ij off the diagonal and −1 on it.
func (f *xfield) simple(i int) xmat {
	m := f.identity()
	c := [3][3]xring{
		{f.zero(), f.gen(0), f.zero()},
		{f.gen(0), f.zero(), f.gen(1)},
		{f.zero(), f.gen(1), f.zero()},
	}
	for j := range 3 {
		if j == i {
			m[i][j] = f.neg(f.one())
		} else {
			m[i][j] = c[i][j]
		}
	}
	return m
}

// rowTimes is the row vector v times m.
func (f *xfield) rowTimes(v [3]xring, m xmat) [3]xring {
	var out [3]xring
	for j := range 3 {
		s := f.zero()
		for k := range 3 {
			s = f.add(s, f.mul(v[k], m[k][j]))
		}
		out[j] = s
	}
	return out
}

func vecKey(v [3]xring) string { return v[0].key() + "|" + v[1].key() + "|" + v[2].key() }

// exactLace is the exact generator's patch: per tile its depth, parent,
// side crossed, and the exact identities of its center, corners and side
// midpoints; the count of tiles around each vertex and edge identity; and
// the shipped generator's counters.
type exactLace struct {
	f                    *xfield
	depth, parent, via   []int
	center               []string
	corners, sides       [][]string
	vertexTiles          map[string]int
	edgeTiles            map[string]int
	omitted              int
	processed, duplicate int
	stopped              string
	pending              int
	// The exact center vectors, for distances.
	centerVec []([3]xring)
	maxCoef   int64
}

// exactGenerate grows the {p,q} patch breadth-first exactly as the
// shipped generator orders it: tiles in queue order, sides 0 to p − 1,
// skipping the side crossed to reach the tile. Side k of the seed is the
// mirror ρ^k s3 ρ^−k with ρ = s2 s1 the rotation carrying corner k to
// corner k + 1, and corner k is ρ^(k−1)·ω1, so side k joins corners k and
// k + 1. A transformation T is stored as the root-basis matrix of T⁻¹,
// since a point f is carried to f∘T⁻¹ = f·M(T⁻¹), and a child T∘σ has
// M((Tσ)⁻¹) = M(σ)·M(T⁻¹).
func exactGenerate(p, q, depth, maxTiles, candidates int) *exactLace {
	f := newXField(p, q)
	s1, s2, s3 := f.simple(0), f.simple(1), f.simple(2)
	rho := f.mulMat(s2, s1)
	rhoInv := f.mulMat(s1, s2)
	// Powers of ρ and ρ⁻¹.
	pow := func(m xmat, n int) xmat {
		out := f.identity()
		for range n {
			out = f.mulMat(out, m)
		}
		return out
	}
	sigma := make([]xmat, p)
	cornerVec := make([][3]xring, p)
	midVec := make([][3]xring, p)
	unit := func(i int) [3]xring {
		var v [3]xring
		for k := range 3 {
			v[k] = f.zero()
		}
		v[i] = f.one()
		return v
	}
	for k := range p {
		// M(ρ^k s3 ρ^−k) = M(ρ)^k·S3·M(ρ⁻¹)^k.
		sigma[k] = f.mulMat(f.mulMat(pow(rho, k), s3), pow(rhoInv, k))
		// Corner k is ρ^(k−1)·ω1 = ω1·M(ρ^(1−k)); side k's midpoint ρ^k·ω2.
		cornerVec[k] = f.rowTimes(unit(0), pow(rho, (p+1-k)%p))
		midVec[k] = f.rowTimes(unit(1), pow(rho, (p-k)%p))
	}
	x := &exactLace{f: f, vertexTiles: map[string]int{}, edgeTiles: map[string]int{}}
	inv := []xmat{}
	tiles := map[string]int{}
	left := map[string]bool{}
	admit := func(m xmat, d, parent, via int) {
		c := f.rowTimes(unit(2), m)
		k := vecKey(c)
		tiles[k] = len(x.center)
		inv = append(inv, m)
		x.depth = append(x.depth, d)
		x.parent = append(x.parent, parent)
		x.via = append(x.via, via)
		x.center = append(x.center, k)
		x.centerVec = append(x.centerVec, c)
		cs, ss := make([]string, p), make([]string, p)
		for j := range p {
			cv := f.rowTimes(cornerVec[j], m)
			cs[j] = vecKey(cv)
			ss[j] = vecKey(f.rowTimes(midVec[j], m))
			x.vertexTiles[cs[j]]++
			x.edgeTiles[ss[j]]++
			for _, v := range cv {
				for _, co := range v {
					x.maxCoef = max(x.maxCoef, co, -co)
				}
			}
		}
		x.corners = append(x.corners, cs)
		x.sides = append(x.sides, ss)
	}
	if maxTiles > 0 {
		admit(f.identity(), 0, -1, -1)
	}
grow:
	for head := 0; head < len(inv); head++ {
		for j := range p {
			if j == x.via[head] {
				continue
			}
			if x.processed == candidates {
				x.stopped, x.pending = "candidates", len(inv)-head
				break grow
			}
			x.processed++
			m := f.mulMat(sigma[j], inv[head])
			k := vecKey(f.rowTimes(unit(2), m))
			if _, ok := tiles[k]; ok {
				x.duplicate++
				continue
			}
			if x.depth[head]+1 > depth {
				if !left[k] {
					left[k] = true
					x.omitted++
				}
				continue
			}
			if len(inv) == maxTiles {
				x.stopped, x.pending = "count", len(inv)-head
				break grow
			}
			admit(m, x.depth[head]+1, head, j)
		}
	}
	return x
}

// coshFromCenter is cosh of the hyperbolic distance between the seed's
// center and tile i's, from the invariant form on dual vectors: with G the
// Gram matrix B(α_i, α_j) = −c_ij/2, the dual form is G⁻¹, and
// cosh d(f, g) = |f·G⁻¹·gᵀ| / √(f·G⁻¹·fᵀ · g·G⁻¹·gᵀ). Computed at 200 bits.
func (x *exactLace) coshFromCenter(i int) float64 {
	f := x.f
	cp := new(big.Float).SetPrec(200).Quo(f.a, big.NewFloat(2))
	cq := new(big.Float).SetPrec(200).Quo(f.b, big.NewFloat(2))
	// G = [[1, −cp, 0], [−cp, 1, −cq], [0, −cq, 1]]; its adjugate.
	one := new(big.Float).SetPrec(200).SetInt64(1)
	sq := func(v *big.Float) *big.Float { return new(big.Float).SetPrec(200).Mul(v, v) }
	sub := func(a, b *big.Float) *big.Float { return new(big.Float).SetPrec(200).Sub(a, b) }
	mul := func(a, b *big.Float) *big.Float { return new(big.Float).SetPrec(200).Mul(a, b) }
	adj := [3][3]*big.Float{
		{sub(one, sq(cq)), cp, mul(cp, cq)},
		{cp, one, cq},
		{mul(cp, cq), cq, sub(one, sq(cp))},
	}
	form := func(u, v [3]*big.Float) *big.Float {
		s := new(big.Float).SetPrec(200)
		for a := range 3 {
			for b := range 3 {
				s.Add(s, mul(mul(u[a], adj[a][b]), v[b]))
			}
		}
		return s
	}
	vals := func(v [3]xring) [3]*big.Float {
		return [3]*big.Float{f.value(v[0]), f.value(v[1]), f.value(v[2])}
	}
	u, w := vals(x.centerVec[0]), vals(x.centerVec[i])
	num := form(u, w)
	den := new(big.Float).SetPrec(200).Sqrt(mul(form(u, u), form(w, w)))
	r, _ := new(big.Float).SetPrec(200).Quo(num, den).Float64()
	return math.Abs(r)
}
